// Prismatic Ribbon (Inspired by iOS Prismatic Flow by @SpaceWall)
// An iridescent 3D ribbon sweeping across pure OLED black with
// flowing spectral thin-film interference, chromatic dispersion, transparent glass, and spotted highlights.

// ============================================================================
// --- CONFIGURATION CONSTANTS (Tweak these to customize shader behavior) -----
// ============================================================================

// --- Glass Transparency & Surface Look ---
#define GLASS_TRANSPARENCY      0.75    // 0.0 = solid opaque pearlescent, 1.0 = clear transparent glass
#define BASE_DIFFUSE_BRIGHTNESS 0.25    // Lower = less opaque body, more glass-like; 0.0 = pure glass
#define FRESNEL_POWER           3.2     // Higher = reflection concentrates strictly at grazing edges

// --- Highlight & Specular Settings ---
#define HIGHLIGHT_INTENSITY     3.2     // Brightness of specular highlight spots
#define HIGHLIGHT_SHARPNESS     85.0    // Specular tightness / glossiness (higher = smaller tighter spots)
#define HIGHLIGHT_SPOTTEDNESS   0.75    // 0.0 = uniform smooth streak, 1.0 = highly concentrated spots
#define HIGHLIGHT_SPOT_COUNT    4.0     // Number of highlight hotspots along the ribbon
#define HIGHLIGHT_DISPERSION    0.10    // Chromatic dispersion (prism color split) in highlights
#define RIM_GLINT_INTENSITY     3.5     // Intensity of razor highlights along curved outer lips

// --- Iridescence & Color Palette ---
#define IRID_FLOW_SPEED         0.25    // Speed of spectral waves flowing along ribbon
#define IRID_SPECTRUM_FREQ      0.32    // Density/frequency of rainbow cycles
#define IRID_FRINGE_INTENSITY   0.14    // Thin-film interference fringe sharpness

// --- Geometry & Ribbon Dimensions ---
#define RIBBON_WIDTH            0.52    // Width of the ribbon band (default: 0.52)
#define RIBBON_THICKNESS        0.038   // Thickness of the ribbon cross-section (default: 0.038)
#define RIBBON_EDGE_ROUNDNESS   0.026   // Roundness bevel of ribbon edges (default: 0.026)
#define RIBBON_SCALE            0.72    // Viewport scale factor (default: 0.72)
#define RIBBON_BREATHING_SPEED  0.35    // Speed of subtle 3D floating/breathing idle motion

// --- Background & Bloom ---
#define CORONA_BLOOM_GLOW       0.12    // Faint chromatic glow around ribbon on black background
#define CORONA_FALLOFF          22.0    // Falloff rate of the background corona
// ============================================================================

mat2 rot2D(float a) {
    float c = cos(a), s = sin(a);
    return mat2(c, -s, s, c);
}

// Map returns vec3(distance, u, v) where:
// - distance: SDF distance
// - u: parameter along the ribbon length (angle phi)
// - v: parameter across the ribbon width (-1.0 to 1.0)
vec3 mapRibbon(vec3 p, float time) {
    // Gentle breathing / floating motion
    p.y += sin(time * RIBBON_BREATHING_SPEED * 1.1) * 0.04;
    p.x += cos(time * RIBBON_BREATHING_SPEED * 0.9) * 0.03;

    // Center and scale to fill portrait and landscape screens elegantly
    p = vec3(-p.x * RIBBON_SCALE + 0.16, p.y * RIBBON_SCALE - 0.10, p.z * RIBBON_SCALE);

    // 3D orientation: dramatic arching swoop
    p.xy = rot2D(0.42) * p.xy;
    p.yz = rot2D(0.58) * p.yz;
    p.xz = rot2D(-0.45) * p.xz;

    float rMaj = 1.45;
    float phi = atan(p.y, p.x);
    float rad = length(p.xy);

    // 3D depth wave along the path
    float zOffset = 0.65 * sin(phi * 0.9 + 0.5) + 0.3 * cos(phi * 1.8);

    vec2 q = vec2(rad - rMaj, p.z - zOffset);

    // Twist along the ribbon: 1.0 * phi ensures C-infinity continuity around the path
    float twist = phi * 1.0 + 1.15 + sin(time * 0.25) * 0.08;
    q = rot2D(twist) * q;

    // Dynamic width: broad face near crest, tapering into depth
    float w = RIBBON_WIDTH + 0.16 * sin(phi + 0.3);

    // Smoothly taper endpoints at bottom
    float fadeEndpoints = smoothstep(-2.6, -1.2, phi) * smoothstep(2.8, 1.4, phi);
    w = max(0.01, w * (0.15 + 0.85 * fadeEndpoints));

    float h = RIBBON_THICKNESS;
    float r = RIBBON_EDGE_ROUNDNESS;

    // Rounded rectangle cross section
    vec2 d = abs(q) - vec2(w - r, h - r);
    float dOut = length(max(d, 0.0));
    float dIn = min(max(d.x, d.y), 0.0);
    float dist = (dOut + dIn - r) / RIBBON_SCALE;

    // Suppress back segment diving into darkness
    if (p.y < -0.8 && p.z < 0.2) {
        dist = max(dist, -p.y - 0.7);
    }

    float u = phi;
    float v = q.x / max(w, 0.001);
    return vec3(dist, u, v);
}

vec3 calcNormal(vec3 p, float time) {
    vec2 e = vec2(0.0015, 0.0);
    float d = mapRibbon(p, time).x;
    return normalize(vec3(
        mapRibbon(p + e.xyy, time).x - d,
        mapRibbon(p + e.yxy, time).x - d,
        mapRibbon(p + e.yyx, time).x - d
    ));
}

// Thin-film iridescent cosine palette with chromatic interference
vec3 spectralPalette(float phase) {
    // 6.2831853 = 2 * PI
    vec3 col = 0.5 + 0.5 * cos(6.2831853 * (phase + vec3(0.00, 0.33, 0.67)));

    // High frequency thin-film optical interference fringes
    float fringe = sin(6.2831853 * phase * 2.5) * IRID_FRINGE_INTENSITY;
    col.r = clamp(col.r + fringe, 0.0, 1.0);
    col.g = clamp(col.g + fringe * 0.3, 0.0, 1.0);
    col.b = clamp(col.b - fringe * 0.5, 0.0, 1.0);
    return col;
}

// ACES filmic tone mapping curve
vec3 acesFilm(vec3 x) {
    float a = 2.51;
    float b = 0.03;
    float c = 2.43;
    float d = 0.59;
    float e = 0.14;
    return clamp((x * (a * x + b)) / (x * (c * x + d) + e), 0.0, 1.0);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (2.0 * fragCoord - iResolution.xy) / min(iResolution.x, iResolution.y);

    // Camera setup with interactive mouse control
    vec2 m = iMouse.xy / iResolution.xy;
    float yaw = (iMouse.z > 0.0) ? (m.x - 0.5) * 2.5 : sin(iTime * 0.15) * 0.1;
    float pitch = (iMouse.z > 0.0) ? (m.y - 0.5) * 2.0 : cos(iTime * 0.12) * 0.08;

    vec3 ro = vec3(0.0, 0.0, 3.4);
    vec3 rd = normalize(vec3(uv, -2.3));

    // Apply camera rotation
    ro.xz = rot2D(yaw) * ro.xz;
    rd.xz = rot2D(yaw) * rd.xz;
    ro.yz = rot2D(pitch) * ro.yz;
    rd.yz = rot2D(pitch) * rd.yz;

    // Localized studio light positions (creates realistic photographic specular hotspots)
    vec3 lightPos1 = vec3(1.6, 1.8, 2.0);
    vec3 lightPos2 = vec3(-1.3, 1.6, -0.6);

    // Raymarch
    float t = 0.8;
    float minD = 10.0;
    vec3 hitData = vec3(0.0);
    bool hit = false;

    for (int i = 0; i < 90; i++) {
        vec3 p = ro + t * rd;
        vec3 res = mapRibbon(p, iTime);
        if (res.x < minD) minD = res.x;
        if (res.x < 0.0012) {
            hit = true;
            hitData = res;
            break;
        }
        t += res.x * 0.82;
        if (t > 6.2) break;
    }

    vec3 col = vec3(0.0);

    if (hit) {
        vec3 pos = ro + t * rd;
        vec3 n = calcNormal(pos, iTime);

        float ndotv = max(dot(n, -rd), 0.0);
        float fresnel = 1.0 - ndotv;
        float fresnelPow = pow(fresnel, FRESNEL_POWER);

        // Animated spectral wave flowing along the ribbon
        float flow = -iTime * IRID_FLOW_SPEED;
        float phase = hitData.y * IRID_SPECTRUM_FREQ + hitData.z * 0.30 + fresnel * 0.70 + flow + 0.45;
        vec3 irid = spectralPalette(phase);

        // Localized studio light vectors
        vec3 l1 = normalize(lightPos1 - pos);
        float diff1 = max(dot(n, l1), 0.0);

        vec3 l2 = normalize(lightPos2 - pos);
        float diff2 = max(dot(n, l2), 0.0);

        vec3 ref = reflect(rd, n);
        float refl1 = max(dot(ref, l1), 0.0);
        float refl2 = max(dot(ref, l2), 0.0);

        // Spottedness modulator: concentrates highlight into distinct oval islands/spots along curve
        float spotWave = sin(hitData.y * HIGHLIGHT_SPOT_COUNT + flow * 0.4 + 1.2) * 0.5 + 0.5;
        float spotFactor = pow(spotWave, 2.5);
        float spotMod = (1.0 - HIGHLIGHT_SPOTTEDNESS) + HIGHLIGHT_SPOTTEDNESS * spotFactor * 1.6;

        // Chromatic dispersion exponents for R, G, B channels
        float expR = HIGHLIGHT_SHARPNESS * (1.0 - HIGHLIGHT_DISPERSION);
        float expG = HIGHLIGHT_SHARPNESS;
        float expB = HIGHLIGHT_SHARPNESS * (1.0 + HIGHLIGHT_DISPERSION);

        vec3 specSpot = vec3(
            pow(refl1, expR),
            pow(refl1, expG),
            pow(refl1, expB)
        ) * spotMod * HIGHLIGHT_INTENSITY;

        // Edge rim glint
        float edgeDist = abs(hitData.z);
        float edgeGlint = pow(edgeDist, 4.5) * fresnelPow * RIM_GLINT_INTENSITY;
        float specRim = pow(refl2, 75.0) * 1.5;

        // Glass Fresnel reflectance (Schlick approximation for clear glass)
        float glassReflectance = 0.04 + 0.96 * fresnelPow;
        float glassTransmission = mix(1.0, glassReflectance, GLASS_TRANSPARENCY);

        // Base body is scaled down by glass transmission, revealing the black background through the center
        vec3 baseCol = irid * (BASE_DIFFUSE_BRIGHTNESS * diff1 + 0.08) * glassTransmission;

        // Rainbow edge rims
        vec3 edgeCol = vec3(
            edgeGlint * (0.8 + 0.4 * irid.r),
            edgeGlint * (0.9 + 0.3 * irid.g),
            edgeGlint * (1.0 + 0.2 * irid.b)
        );

        // Specular glints composite with chromatic dispersion
        vec3 specCol = specSpot + specRim * vec3(0.85, 0.90, 1.0);

        col = baseCol + edgeCol + specCol;

        // Ambient occlusion in self-folding areas
        float ao = 0.5 + 0.5 * sin(hitData.y * 0.8);
        col *= 0.65 + 0.35 * ao;

        // Depth distance fade into darkness
        float fade = clamp((5.4 - t) / 2.0, 0.0, 1.0);
        col *= fade;
    } else {
        // Soft iridescent corona / bloom in deep OLED black
        float glow = exp(-minD * CORONA_FALLOFF) * CORONA_BLOOM_GLOW;
        vec3 glowCol = spectralPalette(uv.x * 0.3 + uv.y * 0.2 - iTime * 0.2);
        col = glow * glowCol;
    }

    // Filmic tone mapping & gamma correction
    col = acesFilm(col);
    col = pow(col, vec3(1.0 / 2.2));

    fragColor = vec4(col, 1.0);
}
